sys_script_include.script:
// Role: keeps the Mapping table in line with each control's "Targets" list and with the CMDB owners,
//       and moves stale evidence to Expired. Nobody edits Mapping rows by hand.
var CPMMapping = Class.create();
CPMMapping.prototype = {
  initialize: function() {
    this.util = new CPMUtil();
  },

  // Role: makes the mappings of one control match its "Targets" list.
  //       New targets get a Missing mapping, removed targets are deactivated (history is kept),
  //       and every owner is brought in line with the CMDB.
  syncControl: function(control) {
    var wanted = this._wanted(control);
    var existing = this._existing(control);
    var controlId = control.getUniqueValue();

    for (var id in wanted) {
      var have = existing[id];
      if (!have) this._create(controlId, id, wanted[id]);
      else if (!have.active || have.owner !== (wanted[id] || '')) this._update(have.id, true, wanted[id]);
    }
    for (var other in existing) {
      if (!(other in wanted) && existing[other].active) this._update(existing[other].id, false);
    }
  },

  // Role: nightly. Copies the CMDB owner onto every active mapping, so a change of owner in the CMDB needs no action here.
  refreshOwners: function() {
    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    mapping.addQuery('active', true);
    mapping.query();
    while (mapping.next()) {
      var owner = (mapping.target.owned_by + '') || (mapping.target.managed_by + '') ||
                  this.util.prop('fallback_owner', '');
      if (owner !== (mapping.getValue('owner') || '')) {
        mapping.setValue('owner', owner);
        mapping.update();
      }
    }
  },

  // Role: nightly. Approved evidence whose date has passed becomes Expired.
  //       If the owner already sent a renewal, the mapping goes back to Awaiting review instead.
  expire: function() {
    var pending = {};
    var evidence = new GlideAggregate('x_1929776_compli_0_evidence');
    evidence.addQuery('status', 'pending');
    evidence.addAggregate('COUNT');
    evidence.groupBy('mapping');
    evidence.query();
    while (evidence.next()) pending[evidence.getValue('mapping')] = true;

    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    mapping.addQuery('state', 'approved');
    mapping.addQuery('valid_until', '<', this.util.today());
    mapping.query();
    while (mapping.next()) {
      mapping.setValue('state', pending[mapping.getUniqueValue()] ? 'awaiting' : 'expired');
      mapping.update();
    }
  },

  // Role: the targets a control should apply to, as { targetId: ownerId }.
  _wanted: function(control) {
    var wanted = {};
    var list = control.getValue('active') == '1' ? (control.getValue('targets') || '') : '';
    var ids = list.split(',').filter(String);
    if (!ids.length) return wanted;

    var ci = new GlideRecord('cmdb_ci');
    ci.addQuery('sys_id', 'IN', ids.join(','));
    ci.query();
    while (ci.next()) wanted[ci.getUniqueValue()] = this.util.ownerOf(ci);
    return wanted;
  },

  // Role: the mappings that already exist for a control, as { targetId: { id, active, owner } }.
  _existing: function(control) {
    var map = {};
    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    mapping.addQuery('control', control.getUniqueValue());
    mapping.query();
    while (mapping.next()) {
      map[mapping.getValue('target')] = {
        id: mapping.getUniqueValue(),
        active: mapping.getValue('active') == '1',
        owner: mapping.getValue('owner') || ''
      };
    }
    return map;
  },

  // Role: creates a blank mapping. Its first state is Missing: the owner has to provide evidence.
  _create: function(controlId, targetId, owner) {
    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    mapping.initialize();
    mapping.setValue('control', controlId);
    mapping.setValue('target', targetId);
    mapping.setValue('owner', owner || '');
    mapping.setValue('state', 'missing');
    mapping.setValue('active', true);
    mapping.insert();
  },

  // Role: switches a mapping on or off, and sets its owner when one is given.
  _update: function(mappingId, active, owner) {
    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    if (!mapping.get(mappingId)) return;
    mapping.setValue('active', active);
    if (owner !== undefined) mapping.setValue('owner', owner || '');
    mapping.update();
  },

  type: 'CPMMapping'
};
